package main
import("fmt";"reflect";"crypto/sha256";"os";"path/filepath";"github.com/minz/minzc/pkg/emulator";"github.com/minz/minzc/pkg/hir";"github.com/minz/minzc/pkg/nanz";"github.com/minz/minzc/pkg/pipeline";"github.com/minz/minzc/pkg/z80asm")
func main(){source:=`fun rd16(arr:^u8,idx:u16)->u16 {var base:u16=idx*2
 return u16(arr[base])+u16(arr[base+1])*256}`;count:=0
for variant:=0;variant<2;variant++{m,e:=nanz.Parse(source,"rd16-independent.nanz");must(e);sourceModule,e:=nanz.Parse(source,"rd16-independent.nanz");must(e);hash:=fmt.Sprintf("%x",sha256.Sum256([]byte(source)));compat,e:=hir.BuildProfileCompatibility(m,hir.ProfileContext{CompilerID:"independent",SemanticsID:"hir-vm-v1",TargetID:"cpm-z80-v1",WorkloadSHA256:hash,HostsSHA256:hash,Dependencies:map[string]string{"rd16-independent.nanz":hash}});must(e);ids,e:=hir.EligibleOrderedByteHelpers(m);must(e);if len(ids)!=1{panic("onehelperexpected")};choices:=map[string]bool{ids[0]:variant==1};must(hir.ApplyOrderedByteHelperChoices(m,compat,choices));_,e=hir.ValidateOrderedByteHelperChoices(sourceModule,m,choices);must(e);s,e:=pipeline.CompileHIRSteps(m,pipeline.Options{AssertMode:"none",UseHIRGrace:true});must(e);_,e=hir.ValidateOrderedByteHelperCompiledChoices(sourceModule,m,choices);must(e);a,e:=z80asm.NewAssembler().AssembleString("ORG 0x8000\nCALL rd16\nDI\nHALT\n"+s.Assembly);must(e);if len(a.Errors)>0{panic(a.Errors)};out:="/tmp/minz-rd16-production-independent-evidence";must(os.WriteFile(filepath.Join(out,fmt.Sprintf("variant%d.a80",variant)),[]byte(s.Assembly),0644));must(os.WriteFile(filepath.Join(out,fmt.Sprintf("variant%d.bin",variant)),a.Binary,0644));fmt.Printf("variant%d bytes%d SHA256%x (harness included)\n",variant,len(a.Binary),sha256.Sum256(a.Binary))
for _,idx:=range []uint16{0,1,255,256,32767,32768,32769,65534,65535}{for _,arr:=range []uint16{0,1,65534,65535}{low:=arr+idx*2;high:=low+1;if protected(int(low),len(a.Binary))||protected(int(high),len(a.Binary)){panic("fixture overlaps code/stack")};memory:=make([]byte,65536);for j:=range memory{memory[j]=byte(j*37+11)};copy(memory[0x8000:],a.Binary);z:=emulator.NewRemogattoZ80();z.Reset();z.SetSMCTracker(nil);must(z.LoadMemory(0,memory));p:=emulator.NewProfiler();z.SetProfiler(p);z.SetRegisters(emulator.Registers{PC:0x8000,SP:0xF000,HL:arr,DE:idx});last:=[65536]uint32{};events:=[]uint16{}
for n:=0;!z.IsHalted();n++{if n>1000{panic("no HALT")};z.Step();delta:=[]uint16{};for j:=0;j<65536;j++{if !protected(j,len(a.Binary)){for k:=last[j];k<p.ReadCount[j];k++{delta=append(delta,uint16(j))}};last[j]=p.ReadCount[j]};if len(delta)>1{panic(fmt.Sprintf("multiple datareads in instruction %v",delta))};events=append(events,delta...)}
want:=uint16(memory[low])+uint16(memory[high])*256;if z.GetRegisters().HL!=want||!reflect.DeepEqual(events,[]uint16{low,high}){panic(fmt.Sprintf("variant%d arr%d idx%d result%d/%d events%v/%v",variant,arr,idx,z.GetRegisters().HL,want,events,[]uint16{low,high}))};for j:=range memory{if j>=0xEF00&&j<0xF100{continue};if p.WriteCount[j]!=0||z.GetMemory(uint16(j))!=memory[j]{panic(fmt.Sprintf("memorywrite %d",j))}};count++}}}
fmt.Printf("PASS %d actual Z80 calls: per-instruction dataread sequence exactly [low,high], no extra byte read, full RAM unchanged except explicit stack; both variants modulo/u16 boundary inputs\n",count)}
func protected(j,n int)bool{return j>=0x8000&&j<0x8000+n||j>=0xEF00&&j<0xF100}
func must(e error){if e!=nil{panic(e)}}
